#!/usr/bin/env python
"""Offline / no-egress checklist for the JANA ADDRESS repo copy (static + dynamic + optional netns run).

What it proves and what it does NOT:
  * STATIC grep finds external URLs and network-library imports that are written in app/ and data/.
  * It CANNOT see URLs generated by third-party libraries at runtime (e.g. FastAPI's /docs page loads
    Swagger UI from cdn.jsdelivr.net, and that string does not exist in this repo). Hence the DYNAMIC pass:
    the app is called in-process through TestClient (no sockets) and the HTML/JSON it returns is grepped.
  * `--no-egress-run` executes the server + a smoke scenario in a fresh network namespace (`unshare -rn`)
    that has no route to the outside; it proves the smoke path works without egress, on THIS machine only.
  * It does NOT prove: Docker image build offline (pip needs PyPI), browser behaviour, fonts loaded by the browser
    from an OS cache, or the judges' machine. Those are listed under `not_verified`.

Exit codes: 0 = no blocking findings; 1 = blocking findings (FAIL); 2 = tool/usage error.
Usage (cwd = repo copy):  python scripts/qa_offline_checklist.py [--root DIR] [--json-out F] [--no-egress-run]
"""
from __future__ import annotations

import argparse
import json
import re
import shutil
import subprocess
import sys
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parent.parent
SCAN_DIRS = ("app", "data")
TEXT_EXT = {".py", ".js", ".html", ".css", ".json", ".md", ".txt", ".csv", ".svg", ".yaml", ".yml", ".toml"}
SKIP_PARTS = {"__pycache__", ".git", ".venv", "qa"}  # data/qa is the QA's own fixture dir; scanned separately below
MAX_BYTES = 2_000_000  # data/synthetic_corpus_v1.json is ~120 KB; anything bigger is skipped and reported

URL_RE = re.compile(r"""(?:(?:https?|wss?|ftp)://[^\s"'<>)\]}`\\]+)""", re.I)
PROTO_REL_RE = re.compile(r"""(?:src|href)\s*=\s*["']//[^"'\s]+""", re.I)
NAMESPACE_ALLOW = ("http://www.w3.org/", "https://www.w3.org/")
RESOURCE_CTX = re.compile(r"""<script[^>]+src|<link[^>]+href|<img[^>]+src|<iframe[^>]+src|<source[^>]+src|@import|url\(""", re.I)
NETCALL_CTX = re.compile(r"""\bfetch\s*\(|XMLHttpRequest|WebSocket|EventSource|sendBeacon|\bimport\s*\(""")
PY_NET_IMPORT = re.compile(
    r"""^\s*(?:import|from)\s+(requests|urllib\.request|urllib3|httpx|aiohttp|http\.client|socket|smtplib|ftplib|telnetlib|websockets|grpc|boto3)\b""",
    re.M)
FETCH_TARGET = re.compile(r"""fetch\s*\(\s*([`'"])(.*?)\1""")


def rel(p: Path, root: Path) -> str:
    return str(p.relative_to(root))


def iter_files(root: Path, base: str):
    for p in sorted((root / base).rglob("*")):
        if p.is_file() and p.suffix.lower() in TEXT_EXT and not (set(p.relative_to(root).parts) & SKIP_PARTS):
            yield p


def classify(line: str, url: str) -> str:
    if url.startswith(NAMESPACE_ALLOW):
        return "xml_namespace"
    if RESOURCE_CTX.search(line):
        return "resource_load"
    if NETCALL_CTX.search(line):
        return "js_network_call"
    return "text_reference"


def static_scan(root: Path) -> dict[str, Any]:
    hits: list[dict[str, Any]] = []
    skipped: list[str] = []
    scanned = 0
    for base in SCAN_DIRS:
        for p in iter_files(root, base):
            if p.stat().st_size > MAX_BYTES:
                skipped.append(rel(p, root))
                continue
            scanned += 1
            for ln, line in enumerate(p.read_text(encoding="utf-8", errors="replace").splitlines(), 1):
                for m in URL_RE.finditer(line):
                    kind = classify(line, m.group(0))
                    hits.append({"file": rel(p, root), "line": ln, "kind": kind, "url": m.group(0)[:160]})
                for m in PROTO_REL_RE.finditer(line):
                    hits.append({"file": rel(p, root), "line": ln, "kind": "resource_load", "url": m.group(0)[:160]})
    blocking = [h for h in hits if h["kind"] in ("resource_load", "js_network_call")]
    review = [h for h in hits if h["kind"] == "text_reference"]
    return {"files_scanned": scanned, "skipped_large_files": skipped, "total_hits": len(hits),
            "blocking": blocking, "needs_human_review": review,
            "ignored_xml_namespaces": sum(1 for h in hits if h["kind"] == "xml_namespace")}


def python_network_imports(root: Path) -> list[dict[str, Any]]:
    found = []
    for p in iter_files(root, "app"):
        if p.suffix != ".py":
            continue
        text = p.read_text(encoding="utf-8", errors="replace")
        for m in PY_NET_IMPORT.finditer(text):
            found.append({"file": rel(p, root), "line": text.count("\n", 0, m.start()) + 1, "module": m.group(1)})
    return found


def js_fetch_targets(root: Path) -> dict[str, Any]:
    out: dict[str, list[str]] = {"same_origin": [], "absolute": []}
    for p in iter_files(root, "app"):
        if p.suffix.lower() not in (".js", ".html"):
            continue
        for m in FETCH_TARGET.finditer(p.read_text(encoding="utf-8", errors="replace")):
            target = m.group(2)
            (out["absolute"] if re.match(r"(?:https?:)?//", target) else out["same_origin"]).append(f"{rel(p, root)}: {target}")
    return out


def docs_configuration(root: Path) -> dict[str, Any]:
    """Look at how FastAPI is constructed: the default /docs page pulls Swagger UI from a CDN."""
    text = (root / "app" / "main.py").read_text(encoding="utf-8")
    m = re.search(r"docs_url\s*=\s*([^,)\s]+)", text)
    r = re.search(r"redoc_url\s*=\s*([^,)\s]+)", text)
    docs, redoc = (m.group(1) if m else "<default '/docs'>"), (r.group(1) if r else "<default '/redoc'>")
    return {"docs_url": docs, "redoc_url": redoc,
            "swagger_ui_default_pulls_cdn": docs not in ("None",), "redoc_default_pulls_cdn": redoc not in ("None",)}


def dynamic_scan(root: Path) -> dict[str, Any]:
    """In-process requests (TestClient, no sockets). Greps every returned body for absolute external URLs."""
    sys.dont_write_bytecode = True
    sys.path.insert(0, str(root))
    try:
        from fastapi.testclient import TestClient
        from app.main import app
    except Exception as exc:  # noqa: BLE001 - report import problems as a tool error, with the cause
        return {"status": "ERROR", "reason": f"cannot import app: {type(exc).__name__}: {exc}"}
    paths = ["/", "/docs", "/redoc", "/openapi.json", "/health", "/api/v1/addresses/demo"]
    static_dir = root / "app" / "static"
    paths += [f"/assets/{p.name}" for p in sorted(static_dir.glob("*")) if p.is_file()]
    results = []
    with TestClient(app) as client:
        for path in paths:
            resp = client.get(path)
            body = resp.text
            urls = sorted({u for u in URL_RE.findall(body) if not u.startswith(NAMESPACE_ALLOW)})
            urls += sorted(set(PROTO_REL_RE.findall(body)))
            results.append({"path": path, "http": resp.status_code, "external_urls": urls})
    blocking = [r for r in results if r["external_urls"] and r["http"] == 200]
    return {"status": "FAIL" if blocking else "PASS", "checked": results, "blocking_paths": [r["path"] for r in blocking]}


def runtime_requirements(root: Path) -> list[dict[str, Any]]:
    """Facts a no-egress run depends on, each marked with how it was verified."""
    req = (root / "requirements.txt").read_text(encoding="utf-8").split() if (root / "requirements.txt").exists() else []
    writes = []
    for p in iter_files(root, "app"):
        if p.suffix == ".py":
            for ln, line in enumerate(p.read_text(encoding="utf-8").splitlines(), 1):
                if re.search(r"""open\([^)]*['"][wa]b?['"]|\.write_text\(|\.write_bytes\(|mkdir\(|os\.makedirs|tempfile""", line):
                    writes.append(f"{rel(p, root)}:{ln}")
    gaz = root / "data" / "gazetteer.json"
    return [
        {"item": "Python >= 3.12 with packages from requirements.txt preinstalled (no pip at runtime)", "packages": req, "verified": "static (requirements.txt read)"},
        {"item": "data/gazetteer.json present and readable; loaded from local disk only", "present": gaz.exists(), "verified": "static"},
        {"item": "app/static/* served locally via /assets (index.html, app.js, style.css); no CDN/fonts", "verified": "see dynamic_scan"},
        {"item": "no runtime writes to disk by app/ code", "write_sites_found": writes, "verified": "static grep"},
        {"item": "no environment variables, API keys, DB or external services required", "verified": "static (no os.environ/getenv in app/)" if not any(
            re.search(r"os\.environ|getenv", p.read_text(encoding='utf-8')) for p in iter_files(root, 'app') if p.suffix == '.py') else "FOUND env usage - review"},
        {"item": "loopback only: uvicorn bound to 127.0.0.1 (or container-internal); judges reach it via localhost", "verified": "no-egress run (if executed)"},
        {"item": "docs/redoc disabled or vendored locally (default /docs needs cdn.jsdelivr.net in the browser)", "verified": "docs_configuration + dynamic_scan"},
        {"item": "DNS/egress firewalled during the judged run: parsing must still succeed", "verified": "no-egress run (if executed)"},
        {"item": "Docker image must be built with the dependencies baked in (pip install happens at BUILD time, needs PyPI)", "verified": "NOT verified here (docker build not run)"},
    ]


INNER_SMOKE = r"""
import json, os, socket, subprocess, sys, time, urllib.request
root = sys.argv[1]
res = {"egress_probe": None, "server": None, "parse": None}
try:
    socket.create_connection(("1.1.1.1", 53), timeout=2).close()
    res["egress_probe"] = "EGRESS POSSIBLE (isolation failed)"
except OSError as e:
    res["egress_probe"] = f"blocked: {type(e).__name__}"
try:
    socket.getaddrinfo("example.com", 80)
    res["dns_probe"] = "DNS RESOLVED (isolation failed)"
except OSError as e:
    res["dns_probe"] = f"blocked: {type(e).__name__}"
port = 18000 + os.getpid() % 1000
proc = subprocess.Popen([sys.executable, "-m", "uvicorn", "app.main:app", "--host", "127.0.0.1", "--port", str(port), "--log-level", "warning"],
                        cwd=root, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, env={**os.environ, "PYTHONDONTWRITEBYTECODE": "1"})
base = f"http://127.0.0.1:{port}"
try:
    ok = False
    for _ in range(300):
        if proc.poll() is not None:
            break
        try:
            if urllib.request.urlopen(base + "/health", timeout=1).status == 200:
                ok = True; break
        except OSError:
            time.sleep(0.1)
    res["server"] = "healthy" if ok else "did not start"
    if ok:
        body = json.dumps([{"id": "n1", "raw_address": "ул. Абая 10, кв 5"}], ensure_ascii=False).encode()
        req = urllib.request.Request(base + "/api/v1/addresses/parse-batch", data=body, headers={"Content-Type": "application/json"}, method="POST")
        r = json.loads(urllib.request.urlopen(req, timeout=20).read())
        res["parse"] = {"records": len(r), "keys": len(r[0]), "house": r[0]["house"], "apartment": r[0]["apartment"]}
        res["index_http"] = urllib.request.urlopen(base + "/", timeout=5).status
finally:
    proc.terminate()
    try: proc.wait(timeout=10)
    except Exception: proc.kill()
print(json.dumps(res, ensure_ascii=False))
"""


def no_egress_run(root: Path, timeout: float = 120.0) -> dict[str, Any]:
    if not shutil.which("unshare") or not shutil.which("ip"):
        return {"status": "NOT RUN", "reason": "`unshare` or `ip` not available"}
    cmd = ["unshare", "-rn", "sh", "-c", f'ip link set lo up && exec "{sys.executable}" -c "$0" "{root}"', INNER_SMOKE]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, check=False)
    except subprocess.TimeoutExpired:
        return {"status": "ERROR", "reason": f"timeout after {timeout}s"}
    if proc.returncode != 0:
        return {"status": "NOT RUN", "reason": f"unshare failed (exit {proc.returncode}): {proc.stderr.strip()[-300:]}"}
    try:
        data = json.loads(proc.stdout.strip().splitlines()[-1])
    except (ValueError, IndexError):
        return {"status": "ERROR", "reason": f"unparsable inner output: {proc.stdout[-200:]!r}"}
    isolated = data["egress_probe"].startswith("blocked") and data.get("dns_probe", "").startswith("blocked")
    works = data["server"] == "healthy" and bool(data.get("parse")) and data["parse"]["keys"] == 14
    return {"status": "PASS" if isolated and works else "FAIL", "isolation_proven": isolated, "smoke_ok": works, "detail": data,
            "scope": "network namespace without any external interface; loopback only; this machine only"}


NOT_VERIFIED = [
    "Docker image build / container start without Internet (pip install needs PyPI at build time)",
    "Browser-side behaviour (UI fonts/icons from OS cache, extensions); only server responses were grepped",
    "Third-party library code paths not exercised by the paths listed in dynamic_scan",
    "Judges' target machine, its OS firewall and Python/Docker versions",
    "Cold-start timing under a firewalled network (see scripts/qa_perf.py --cold-start)",
]


def build_report(root: Path, do_netns: bool) -> dict[str, Any]:
    static = static_scan(root)
    imports = python_network_imports(root)
    docs = docs_configuration(root)
    dyn = dynamic_scan(root)
    checks = {
        "static_external_urls_in_app_data": "FAIL" if static["blocking"] else "PASS",
        "python_network_imports_in_app": "FAIL" if imports else "PASS",
        "docs_pulls_cdn_by_configuration": "FAIL" if (docs["swagger_ui_default_pulls_cdn"] or docs["redoc_default_pulls_cdn"]) else "PASS",
        "dynamic_responses_free_of_external_urls": dyn["status"],
    }
    netns = no_egress_run(root) if do_netns else {"status": "NOT RUN", "reason": "--no-egress-run not requested"}
    checks["no_egress_smoke_run"] = netns["status"]
    failing = [k for k, v in checks.items() if v in ("FAIL", "ERROR")]
    return {
        "tool": "scripts/qa_offline_checklist.py", "root": str(root), "verdict": "FAIL" if failing else "PASS",
        "failing_checks": failing, "checks": checks,
        "static_scan": static, "python_network_imports": imports, "js_fetch_targets": js_fetch_targets(root),
        "docs_configuration": docs, "dynamic_scan": dyn, "no_egress_run": netns,
        "runtime_requirements": runtime_requirements(root), "not_verified": NOT_VERIFIED,
    }


def summary(rep: dict[str, Any]) -> str:
    lines = [f"OFFLINE CHECKLIST  verdict={rep['verdict']}  root={rep['root']}", ""]
    for k, v in rep["checks"].items():
        lines.append(f"  [{v:7s}] {k}")
    for h in rep["static_scan"]["blocking"][:15]:
        lines.append(f"    blocking: {h['file']}:{h['line']} {h['kind']} {h['url']}")
    for h in rep["static_scan"]["needs_human_review"][:15]:
        lines.append(f"    review  : {h['file']}:{h['line']} {h['url']}")
    for i in rep["python_network_imports"]:
        lines.append(f"    net-import: {i['file']}:{i['line']} {i['module']}")
    for r in rep["dynamic_scan"].get("checked", []):
        if r["external_urls"]:
            lines.append(f"    dynamic: GET {r['path']} -> HTTP {r['http']} external: {r['external_urls'][:4]}")
    lines += ["", "runtime requirements for a no-egress run:"]
    lines += [f"  - {r['item']}  [{r['verified']}]" for r in rep["runtime_requirements"]]
    lines += ["", "NOT VERIFIED here:"] + [f"  - {x}" for x in rep["not_verified"]]
    return "\n".join(lines)


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="Offline/no-egress checklist (static + dynamic + optional netns run).")
    ap.add_argument("--root", type=Path, default=ROOT)
    ap.add_argument("--json-out", type=Path)
    ap.add_argument("--no-egress-run", action="store_true", help="run server+smoke inside `unshare -rn` (needs unprivileged userns)")
    ap.add_argument("--quiet", action="store_true", help="no JSON on stdout")
    args = ap.parse_args(argv)
    try:
        rep = build_report(args.root.resolve(), args.no_egress_run)
    except OSError as exc:
        print(f"tool error: {exc}", file=sys.stderr)
        return 2
    print(summary(rep), file=sys.stderr)
    if args.json_out:
        args.json_out.write_text(json.dumps(rep, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
    if not args.quiet:
        print(json.dumps(rep, ensure_ascii=False, indent=1))
    return 0 if rep["verdict"] == "PASS" else 1


if __name__ == "__main__":
    sys.exit(main())
